package industries.leeway.devicebridge

import org.json.JSONObject
import org.junit.Assert.*
import org.junit.Test
import java.net.InetAddress
import java.net.ServerSocket
import java.net.Socket
import kotlin.concurrent.thread

class LocalBridgeMalformedRequestTest {
    private fun send(raw: String): Int {
        ServerSocket(0, 1, InetAddress.getByName("127.0.0.1")).use { server ->
            server.soTimeout = 3000
            val worker = thread {
                LocalBridgeHttpHandler.serve(server.accept(), LocalBridgeHttpHandler.Dependencies(
                    health = { JSONObject().put("ok", true) },
                    ownerBootstrap = { JSONObject().put("ok", false) },
                    accessEnabled = { true },
                    bearerMatches = { it == "fixture-token" },
                    protectedRead = { if (it == "/provisioning/plan") JSONObject().put("ok", true) else null },
                    recordRead = { }
                ))
            }
            val status = Socket("127.0.0.1", server.localPort).use { socket ->
                socket.soTimeout = 3000
                socket.getOutputStream().write(raw.toByteArray())
                socket.shutdownOutput()
                socket.getInputStream().bufferedReader().readLine()
                    ?.split(" ")?.getOrNull(1)?.toInt() ?: -1
            }
            worker.join(3000)
            return status
        }
    }
    @Test fun invalidTargetDenied() = assertEquals(400, send("GET https://other.host/ HTTP/1.1\r\n\r\n"))
    @Test fun missingHeaderTerminatorDenied() = assertEquals(400, send("GET /provisioning/plan HTTP/1.1\r\nHost: local"))
    @Test fun oversizedHeaderDenied() = assertEquals(431, send("GET /provisioning/plan HTTP/1.1\r\nX-Test: \r\n\r\n"))
    @Test fun oversizedRequestLineDenied() = assertEquals(400, send("GET  HTTP/1.1\r\n\r\n"))
    @Test fun validAuthStillWorks() = assertEquals(200, send("GET /provisioning/plan HTTP/1.1\r\nAuthorization: Bearer fixture-token\r\n\r\n"))
}
